		// Token: 0x06000670 RID: 1648 RVA: 0x00169480 File Offset: 0x00167680
		private void loadNextDay(bool incrementDay, bool savegame)
		{
			int num = this.sc.currentDay - 1;
			bool flag = (int)this.sc.maxDay() >= num || this.sc.cheatsOn;
			if (savegame && flag)
			{
				int num2 = this.sc.df + 1;
				this.sc.days[this.sc.currentDay] = num2;
				this.sc.SaveGame();
				this.sc.weFailed = 0;
			}
			this.sc.protectScreen = false;
			this.exitNicer();
			bool flag2 = false;
			if (incrementDay || !flag2)
			{
				this.sc.gameSeed++;
			}
			if (incrementDay)
			{
				this.sc.currentDay++;
				if (this.sc.currentDay > 101)
				{
					this.sc.currentDay = 1;
				}
			}
			this.sc.gameSpectate = 1;
			if (!this.isTrialMode)
			{
				if (!flag)
				{
					int milks = this.sc.milks;
					int hulks = this.sc.hulks;
					int pills = this.sc.pills;
					int grenades = this.sc.grenades;
					int rockets = this.sc.rockets;
					this.sc.resetGame();
					this.sc.LoadGame(false);
					if (savegame)
					{
						this.sc.milks = milks;
						this.sc.hulks = hulks;
						this.sc.pills = pills;
						this.sc.grenades = grenades;
						this.sc.rockets = rockets;
					}
					else
					{
						this.sc.milks = 0;
						this.sc.hulks = 0;
						this.sc.pills = 0;
						this.sc.grenades = 0;
						this.sc.rockets = 0;
					}
				}
				else
				{
					this.sc.resetGame();
					this.sc.LoadGame(false);
				}
			}
			this.sc.SavePrefs();
			this.sc.isLoading = true;
			this.sc.leavingGame = true;
			this.sc.tempPistol = this.myPlayer.primaryChoice;
			this.sc.tempRifle = this.myPlayer.secondaryChoice;
			this.sc.tempAmmo = this.myPlayer.ammo[this.myPlayer.secondaryChoice];
			this.sc.tempMag = this.myPlayer.mag[this.myPlayer.secondaryChoice];
			this.sc.redContrast = 128;
			this.sc.contrastBU = 128;
			LoadingScreen1.Load(base.ScreenManager, true, new PlayerIndex?(this.playerIndex), null, new GameScreen[]
			{
				new BloodnBacon(null)
			});
		}

