			this.tickOffset = 0;
			this.timeFrame = this.getTick(this.startGame) + this.tickOffset;
			this.lasttimeDelay = this.timeFrame;
			this.syncCountdown = 800;
			if (Princess.cuttyCount > 0)
			{
				Princess.seed = seed;
			}
			Random random = new Random(seed);
			Vector3 vector = Vector3.Zero;
			int num = random.Next(9000, 22000);
			for (int i = 0; i < this.sc.boarCount; i++)
			{
				num++;
				int num2 = this.sc.boar1Variant;
				int num3 = this.sc.boar1Spawn;
				int num4;
				if (random.Next(1, 100) < this.sc.boar2Count)
				{
					num4 = 2;
					num2 = this.sc.boar2Variant;
					vector = this.randomPosition(this.sc.boar2Spawn, ref random);
					num3 = this.sc.boar2Spawn;
				}
				else
				{
					num4 = 1;
					num2 = this.sc.boar1Variant;
					vector = this.randomPosition(this.sc.boar1Spawn, ref random);
					num3 = this.sc.boar1Spawn;
				}
				n.dupe.Add(new boarDupe(num4, num2, vector, 1, num, this.timeFrame, this.sc, this.sc.dayTime, num3, false));
			}
			Randoms.initRandom(n.dupe[0].seed);
		}

